import { z } from "zod";
import { MarkDownContent } from "../other.mjs";
const zBaseOption = z.object({
    icon: z.string().optional(),
    label: z.string().optional(),
    action: z.string(),
});
const zActionOption = zBaseOption.refine((data) => (data.action ? data.icon || data.label : true), {
    message: "Either icon or label is required",
    path: ["icon", "label"],
});
const zDismissOption = zBaseOption.transform((val) => val && !val.icon && !val.label ? Object.assign(Object.assign({}, val), { icon: "x" }) : val);
const zInfoBarProps = z.object({
    content: z.instanceof(MarkDownContent).or(z.string()),
    icon: z.string().optional(),
    action: zActionOption.optional(),
    dismiss: zDismissOption.optional(),
    variant: z
        .enum(["info", "alert", "success", "error"])
        .optional()
        .default("info"),
});
export function InfoBar(define) {
    return define("InfoBar")
        .props(zInfoBarProps)
        .userEvents({
        click: [z.string(), null],
    })
        .render((props) => ({
        id: props.id,
        content: props.content,
        icon: props.icon,
        action: props.action,
        dismiss: props.dismiss,
        variant: props.variant,
    }));
}
